window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-14f0c4a6b79e8553"]={"versions": [{"id": "FIG-14f0c4a6b79e8553", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>):\n<ul class=\"fig-list\"><li>Oberstes Hüll-Element der Systembeschreibung.\n</li><li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).\n</li><li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.\n</li></ul>\n</li><li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).\n</li></ul>\n</li><li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):\n<ul class=\"fig-list\"><li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong>:\n<ul class=\"fig-list\"><li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+component</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.\n</li><li><code>+connector</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.\n</li></ul>\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Basistyp aller Software-Komponenten.\n</li><li>Aggregiert <code>+port</code> [0..\\*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.\n</li><li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Interaktionspunkt einer SW-C.\n</li><li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).\n</li></ul>\n</li><li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) &amp; <strong><code>AssemblySwConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.\n</li><li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:\n<ul class=\"fig-list\"><li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.\n</li><li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (Methodik &amp; Binding)</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\"><li><strong>System Design &amp; ECU Extraction:</strong> \n<ul class=\"fig-list\"><li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).\n</li><li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.\n</li></ul>\n</li><li><strong>Hierarchisches Flattening:</strong>\n<ul class=\"fig-list\"><li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.\n</li><li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.\n</li></ul>\n</li><li><strong>Variationspunkt-Bindung:</strong>\n<ul class=\"fig-list\"><li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) → Komponenten- und Konnektor-Topologie (<code>postBuild</code>) → Port-Schnittstellen (<code>preCompileTime</code>).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>RTE-Generierung:</strong> \n<ul class=\"fig-list\"><li>Der <code>RootSwCompositionPrototype</code> ist die verbindliche Wurzel für den RTE-Generator. Nur Komponenten und Ports, die transitiv über diesen Pfad erreichbar sind, werden in den RTE-Contract- und Generation-Phasen berücksichtigt.\n</li><li>Unverbundene R-Ports oder offene P-Ports führen je nach Konfiguration zu Warnungen oder Fehlern während der RTE-Validierung.\n</li></ul>\n</li><li><strong>Instanzreferenzierung (<code>«instanceRef»</code>):</strong> \n<ul class=\"fig-list\"><li>Entwickler von Generierungs- und Import-Tools müssen sicherstellen, dass <code>AssemblySwConnector</code> vollständige Komponenten-Instanzpfade (<code>contextComponent</code>) deklariert. Ein Verweis rein auf den <code>PortPrototype</code> ohne Kontext ist im Metamodell ungültig, da derselbe <code>SwComponentType</code> mehrfach instanziiert werden kann.\n</li></ul>\n</li><li><strong>Variationspunkte &amp; Post-Build-Fähigkeit:</strong>\n<ul class=\"fig-list\"><li>Da <code>+component</code> und <code>+connector</code> als <code>vh.latestBindingTime = postBuild</code> annotiert sind, können Komponenteninstanzen und Assembly-Verbindungen theoretisch bis in die Post-Build-Phase variiert werden (z. B. Aktivierung/Deaktivierung bestimmter Features). Die Port-Definition (<code>preCompileTime</code>) erfordert jedoch zwingend ein fixes Interface-Layout vor der Kompilierung des Codes.\n</li></ul>\n</li><li><strong>BSW- und Service-Integration:</strong>\n<ul class=\"fig-list\"><li><code>ServiceSwComponentType</code> ist als Subklasse von <code>AtomicSwComponentType</code> abgebildet. BSW-Module (wie Dem, NvM, ComM), die Service-Ports bereitstellen, werden über dieselben Mechanismen (<code>SwComponentPrototype</code>, <code>AssemblySwConnector</code>) an Applikations-SW-Cs angebunden.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-b32a5ffcd8a1ce29", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li>Oberstes Hüll-Element der Systembeschreibung.\n</li><li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).\n</li><li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.\n</li></ul>\n</li><li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).\n</li></ul>\n</li><li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):\n<ul class=\"fig-list\"><li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong>:\n<ul class=\"fig-list\"><li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.\n</li><li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.\n</li></ul>\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Basistyp aller Software-Komponenten.\n</li><li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.\n</li><li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Interaktionspunkt einer SW-C.\n</li><li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).\n</li></ul>\n</li><li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) &amp; <strong><code>AssemblySwConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.\n</li><li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:\n<ul class=\"fig-list\"><li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.\n</li><li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\"><li><strong>System Design &amp; ECU Extraction:</strong> \n<ul class=\"fig-list\"><li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).\n</li><li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.\n</li></ul>\n</li><li><strong>Hierarchisches Flattening:</strong>\n<ul class=\"fig-list\"><li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.\n</li><li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.\n</li></ul>\n</li><li><strong>Variationspunkt-Bindung:</strong>\n<ul class=\"fig-list\"><li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) → Komponenten- und Konnektor-Topologie (<code>postBuild</code>) → Port-Schnittstellen (<code>preCompileTime</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kardinalitäts- und Typ-Integrität:</strong>\n<ul class=\"fig-list\"><li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).\n</li><li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.\n</li><li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).\n</li></ul>\n</li><li><strong>Variabilitäts- und Splitbarkeitsregeln:</strong>\n<ul class=\"fig-list\"><li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.\n</li><li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-6323dc5ba8baa5e2", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li>Oberstes Hüll-Element der Systembeschreibung.\n</li><li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>).\n</li><li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.\n</li></ul>\n</li><li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).\n</li></ul>\n</li><li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):\n<ul class=\"fig-list\"><li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong>:\n<ul class=\"fig-list\"><li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.\n</li><li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.\n</li></ul>\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Basistyp aller Software-Komponenten.\n</li><li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.\n</li><li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Interaktionspunkt einer SW-C.\n</li><li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).\n</li></ul>\n</li><li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) &amp; <strong><code>AssemblySwConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.\n</li><li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:\n<ul class=\"fig-list\"><li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.\n</li><li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\"><li><strong>System Design &amp; ECU Extraction:</strong> \n<ul class=\"fig-list\"><li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).\n</li><li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.\n</li></ul>\n</li><li><strong>Hierarchisches Flattening:</strong>\n<ul class=\"fig-list\"><li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.\n</li><li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.\n</li></ul>\n</li><li><strong>Variationspunkt-Bindung:</strong>\n<ul class=\"fig-list\"><li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) → Komponenten- und Konnektor-Topologie (<code>postBuild</code>) → Port-Schnittstellen (<code>preCompileTime</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kardinalitäts- und Typ-Integrität:</strong>\n<ul class=\"fig-list\"><li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).\n</li><li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.\n</li><li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).\n</li></ul>\n</li><li><strong>Variabilitäts- und Splitbarkeitsregeln:</strong>\n<ul class=\"fig-list\"><li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.\n</li><li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-1581a17468f50425", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> AUTOSAR-Metamodell-Ausschnitt (M2), dargestellt als UML-Klassendiagramm.\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der Strukturhierarchie zur Verankerung der Software-Architektur auf System- bzw. Steuergeräteebene. Es definiert, wie über <code>RootSwCompositionPrototype</code> eine Wurzel-Komposition (<code>CompositionSwComponentType</code>) in ein <code>System</code> eingebettet wird, wie die hierarchische Zerlegung in Software-Komponenten-Prototypen (<code>SwComponentPrototype</code>) und Ports erfolgt und wie diese Struktur über die Relation <code>ecuExtract</code> an die Steuergerätekonfiguration (<code>EcucValueCollection</code>) angebunden wird.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metaklassen &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>System</code></strong> (<code>«ARElement»</code>, <code>«AtpStructureElement»</code>, <code>«UploadableDesignElement»</code>):\n<ul class=\"fig-list\"><li>Oberstes Hüll-Element der Systembeschreibung.\n</li><li>Hält die Komposition <code>+rootSoftwareComposition</code> [0..1] auf <code>RootSwCompositionPrototype</code> (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>systemDesignTime</code>, <code>mmt.RestrictToStandards = CP</code>).\n</li><li>Referenziert via Assoziation <code>+ecuExtract</code> [0..1] die Zielkonfiguration <code>EcucValueCollection</code>.\n</li></ul>\n</li><li><strong><code>EcucValueCollection</code></strong> (<code>«ARElement»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die gesammelten Parameterwerte der BSW- und RTE-Konfiguration des Steuergeräts (ECU Configuration / ECU Extract).\n</li></ul>\n</li><li><strong><code>RootSwCompositionPrototype</code></strong> (<code>«AtpPrototype»</code>, <code>«Identifiable»</code>):\n<ul class=\"fig-list\"><li>Spezifischer Prototyp zur Instanziierung der Top-Level-Komposition auf System- oder ECU-Ebene.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+softwareComposition</code> [0..1] (<code>{redefines atpType}</code>) auf <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>CompositionSwComponentType</code></strong>:\n<ul class=\"fig-list\"><li>Kompositionselement, das weitere Komponenten und deren Verbindungen kapselt.\n</li><li>Aggregiert per Komposition:\n<ul class=\"fig-list\"><li><code>+component</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>postBuild</code>): Kind-Instanzen vom Typ <code>SwComponentPrototype</code>.\n</li><li><code>+connector</code> [0..*] (<code>«atpVariation, atpSplitable»</code>): Verbinder zur Verschaltung der Komponentenports.\n</li></ul>\n</li></ul>\n</li><li><strong><code>SwComponentPrototype</code></strong> (<code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Repräsentiert die konkrete Instanz einer atomaren oder hierarchischen Komponente.\n</li><li>Typisiert über <code>«isOfType»</code> via <code>+type</code> [0..1] (<code>{redefines atpType}</code>) auf <code>SwComponentType</code>.\n</li></ul>\n</li><li><strong><code>SwComponentType</code></strong> (<code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code>, <code>«AtpType»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Basistyp aller Software-Komponenten.\n</li><li>Aggregiert <code>+port</code> [0..*] (<code>«atpVariation, atpSplitable»</code>, Binding Time: <code>preCompileTime</code>) auf <code>PortPrototype</code>.\n</li><li>Spezialisierungen: <code>AtomicSwComponentType</code> (u. a. weiter spezialisiert zu <code>ServiceSwComponentType</code>) sowie <code>CompositionSwComponentType</code>.\n</li></ul>\n</li><li><strong><code>PortPrototype</code></strong> (<code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>):\n<ul class=\"fig-list\"><li>Abstrakter Interaktionspunkt einer SW-C.\n</li><li>Spezialisiert in <code>AbstractRequiredPortPrototype</code> (R-Port) und <code>AbstractProvidedPortPrototype</code> (P-Port).\n</li></ul>\n</li><li><strong><code>SwConnector</code></strong> (<code>«AtpStructureElement»</code>) &amp; <strong><code>AssemblySwConnector</code></strong>:\n<ul class=\"fig-list\"><li><code>AssemblySwConnector</code> spezialisiert <code>SwConnector</code> für die Verbindung zweier Komponenten auf derselben Hierarchieebene.\n</li><li>Hält gerichtete <code>«instanceRef»</code>-Beziehungen:\n<ul class=\"fig-list\"><li><code>+requester</code> [0..1] auf <code>AbstractRequiredPortPrototype</code>.\n</li><li><code>+provider</code> [0..1] auf <code>AbstractProvidedPortPrototype</code>.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als statisches M2-Strukturdiagramm bildet das Schaubild kein Laufzeit-Sequenzdiagramm ab, sondern steuert den <strong>AUTOSAR-Methodik-Workflow</strong> bei Extraktion und Instanziierung:</p>\n<ol class=\"fig-list\"><li><strong>System Design &amp; ECU Extraction:</strong> \n<ul class=\"fig-list\"><li>Definition der Gesamtsystem-Komposition (<code>systemDesignTime</code>).\n</li><li>Bei der Erstellung des ECU-Extracts wird der <code>RootSwCompositionPrototype</code> auf die für dieses spezifische Steuergerät relevanten SW-Cs zugeschnitten und via <code>+ecuExtract</code> mit der <code>EcucValueCollection</code> verknüpft.\n</li></ul>\n</li><li><strong>Hierarchisches Flattening:</strong>\n<ul class=\"fig-list\"><li>Der Konfigurationsgenerator expandiert die <code>CompositionSwComponentType</code>-Bäume rekursiv über alle <code>SwComponentPrototype</code>-Ebenen hinweg.\n</li><li><code>AssemblySwConnector</code>-Instanzreferenzen (<code>«instanceRef»</code>) lösen hierarchische Pfade (Context-Ketten) zu den Zielports (<code>provider</code> und <code>requester</code>) atomarer SW-Cs auf.\n</li></ul>\n</li><li><strong>Variationspunkt-Bindung:</strong>\n<ul class=\"fig-list\"><li>Bindung erfolgt gestaffelt: Systemzuschnitt (<code>systemDesignTime</code>) → Komponenten- und Konnektor-Topologie (<code>postBuild</code>) → Port-Schnittstellen (<code>preCompileTime</code>).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Kardinalitäts- und Typ-Integrität:</strong>\n<ul class=\"fig-list\"><li>Die typisierende Zuordnung <code>+softwareComposition</code> von <code>RootSwCompositionPrototype</code> auf <code>CompositionSwComponentType</code> ist optional (<code>0..1</code>).\n</li><li>Ein <code>System</code> kann optional (<code>0..1</code>) genau eine Root-Komposition (<code>+rootSoftwareComposition</code>) besitzen.\n</li><li><code>AssemblySwConnector</code> referenziert über <code>«instanceRef»</code> jeweils maximal einen Provider- und einen Requester-Port (<code>0..1</code>).\n</li></ul>\n</li><li><strong>Variabilitäts- und Standard-Einschränkungen:</strong>\n<ul class=\"fig-list\"><li>Die Aggregationen <code>+rootSoftwareComposition</code>, <code>+component</code>, <code>+connector</code> und <code>+port</code> sind als <code>«atpVariation, atpSplitable»</code> modelliert; damit sind sie über XML-Dateigrenzen hinweg aufteilbar und unterstützen AUTOSAR-Variantenbildung.\n</li><li>Die jeweils annotierten Bindungszeiten (<code>systemDesignTime</code>, <code>postBuild</code>, <code>preCompileTime</code>) schränken den spätestmöglichen Zeitpunkt der Variantenauflösung verbindlich ein.\n</li><li>Die Komposition <code>+rootSoftwareComposition</code> ist durch das Tag <code>mmt.RestrictToStandards = CP</code> explizit auf die Classic Platform eingeschränkt.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-14f0c4a6b79e8553", "to": "FIG-b32a5ffcd8a1ce29", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>System</code></strong>: Stereotyp <code>«UploadableDesignElement»</code> hinzugefügt (neben <code>«ARElement»</code> und <code>«AtpStructureElement»</code>).\n</li><li><strong><code>RootSwCompositionPrototype</code></strong>: Kardinalität der typisierenden Assoziation <code>+softwareComposition</code> zu <code>CompositionSwComponentType</code> von <code>1</code> auf <code>0..1</code> geändert.\n</li></ul>"}, {"from": "FIG-b32a5ffcd8a1ce29", "to": "FIG-6323dc5ba8baa5e2", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6323dc5ba8baa5e2", "to": "FIG-1581a17468f50425", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Aggregation <code>+rootSoftwareComposition</code></strong>: Im Notizfeld für <code>«atpVariation» Tags</code> wurde der Tag <code>mmt.RestrictToStandards = CP</code> ergänzt.\n</li></ul>"}]};
